import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Img,
  staticFile,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";

export const fps = 25;

const COLORS = {
  red: "#FF0000",
  redDark: "#CC0000",
  redGlow: "rgba(255,0,0,0.15)",
  white: "#FFFFFF",
  offWhite: "rgba(255,255,255,0.85)",
  muted: "rgba(255,255,255,0.45)",
  bg: "#0A0A0A",
  darkCard: "rgba(255,255,255,0.04)",
  border: "rgba(255,255,255,0.08)",
};

const TRANSITION = 12;

const BlackScreen: React.FC = () => (
  <AbsoluteFill style={{ backgroundColor: COLORS.bg }} />
);

const Background: React.FC<{ opacity?: number }> = ({ opacity = 1 }) => (
  <AbsoluteFill style={{ opacity }}>
    <Img
      src={staticFile("assets/backgrounds/background.png")}
      style={{ width: "100%", height: "100%", objectFit: "cover" }}
    />
    {/* Dark overlay so text stays readable */}
    <AbsoluteFill
      style={{ backgroundColor: "rgba(8,4,12,0.72)" }}
    />
  </AbsoluteFill>
);

// ─── Animated noise / scanline overlay for cinematic feel ────────────────────
const Vignette: React.FC = () => (
  <AbsoluteFill
    style={{
      background:
        "radial-gradient(ellipse at center, transparent 50%, rgba(0,0,0,0.65) 100%)",
      pointerEvents: "none",
    }}
