// ─── SCENE 1: 500 Hours — big clock, fast energy ─────────────────────────────

const Scene1: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Everything hits fast — this is a 4-second scene
  const bgProgress = spring({ frame, fps, delay: 0, config: { damping: 200 } });

  const counterProgress = spring({
    frame, fps, delay: 2, config: { damping: 80 },
  });
  const counter = Math.round(interpolate(counterProgress, [0, 1], [0, 500]));

  const hoursProgress = spring({ frame, fps, delay: 10, config: { damping: 200 } });
  const subProgress = spring({ frame, fps, delay: 18, config: { damping: 200 } });
  const clockProgress = spring({ frame, fps, delay: 5, config: { damping: 200 } });

  // Hyper-fast clock hands
  const secondHandRot = interpolate(frame, [0, 100], [0, 1080], { extrapolateRight: "clamp" });
  const minuteHandRot = interpolate(frame, [0, 100], [0, 360], { extrapolateRight: "clamp" });
  const tickRingRot = frame * 0.6;

  // Pulsing red glow
  const glowPulse = Math.sin(frame * 0.18) * 0.5 + 0.5;

  // Horizontal lines that shoot across
  const lineProgress1 = spring({ frame, fps, delay: 8, config: { damping: 200 } });
  const lineProgress2 = spring({ frame, fps, delay: 12, config: { damping: 200 } });

  return (
    <AbsoluteFill style={{ fontFamily: "'Inter', sans-serif" }}>
      <Background opacity={interpolate(bgProgress, [0, 1], [0, 1])} />
      <Vignette />

      {/* Animated red radial burst */}
      <AbsoluteFill style={{ display: "flex", alignItems: "center", justifyContent: "center" }}>
        <div style={{
          position: "absolute",
          width: interpolate(glowPulse, [0, 1], [1200, 1600]),
          height: interpolate(glowPulse, [0, 1], [1200, 1600]),
          borderRadius: "50%",
          background: `radial-gradient(circle, rgba(255,0,0,${interpolate(glowPulse, [0, 1], [0.18, 0.28])}) 0%, transparent 65%)`,
          opacity: clockProgress,
          transition: "all 0.1s",
        }} />
      </AbsoluteFill>

      {/* Orbiting tick ring */}
      <AbsoluteFill style={{
        display: "flex", alignItems: "center", justifyContent: "center",
        opacity: interpolate(clockProgress, [0, 1], [0, 0.8]),
      }}>
        <svg width="1000" height="1000" viewBox="0 0 1000 1000"
          style={{ transform: `rotate(${tickRingRot}deg)` }}>
          {Array.from({ length: 60 }).map((_, i) => {
            const angle = (i / 60) * 2 * Math.PI;
            const isLong = i % 5 === 0;
            const r1 = isLong ? 455 : 465;
            const r2 = 480;
            const x1 = 500 + Math.cos(angle) * r1;
            const y1 = 500 + Math.sin(angle) * r1;
            const x2 = 500 + Math.cos(angle) * r2;
            const y2 = 500 + Math.sin(angle) * r2;
            return (
              <line key={i} x1={x1} y1={y1} x2={x2} y2={y2}
                stroke={isLong ? COLORS.red : "rgba(255,255,255,0.3)"}
                strokeWidth={isLong ? 5 : 2} />
            );
          })}
          <circle cx="500" cy="500" r="445" fill="none" stroke="rgba(255,255,255,0.04)" strokeWidth="1" />
        </svg>
      </AbsoluteFill>

      {/* Clock face */}
      <AbsoluteFill style={{
        display: "flex", alignItems: "center", justifyContent: "center",
        opacity: clockProgress,
      }}>
        <svg width="720" height="720" viewBox="0 0 720 720"
          style={{ transform: `scale(${interpolate(clockProgress, [0, 1], [0.6, 1])})` }}>
          <circle cx="360" cy="360" r="340" fill="none"
            stroke="rgba(255,255,255,0.06)" strokeWidth="2" />
          {/* Red sweep arc */}
          <circle cx="360" cy="360" r="340" fill="none" stroke={COLORS.red}
            strokeWidth="4"
            strokeDasharray={`${2 * Math.PI * 340}`}
            strokeDashoffset={interpolate(clockProgress, [0, 1], [2 * Math.PI * 340, 0])}
            transform="rotate(-90 360 360)" opacity="0.6" />
          <circle cx="360" cy="360" r="310" fill="rgba(0,0,0,0.2)" />
          {/* Hour markers */}
          {Array.from({ length: 12 }).map((_, i) => {
            const a = (i / 12) * 2 * Math.PI - Math.PI / 2;
            return (
              <line key={i}
                x1={360 + Math.cos(a) * 280} y1={360 + Math.sin(a) * 280}
                x2={360 + Math.cos(a) * 305} y2={360 + Math.sin(a) * 305}
                stroke="rgba(255,255,255,0.35)" strokeWidth="5" strokeLinecap="round" />
            );
          })}
          {/* Minute hand */}
          <line x1="360" y1="360" x2="360" y2="100"
            stroke="rgba(255,255,255,0.8)" strokeWidth="6" strokeLinecap="round"
            transform={`rotate(${minuteHandRot}, 360, 360)`} />
          {/* Second hand — blazing fast */}
          <line x1="360" y1="380" x2="360" y2="80"
            stroke={COLORS.red} strokeWidth="4" strokeLinecap="round"
            transform={`rotate(${secondHandRot}, 360, 360)`} />
          <circle cx="360" cy="360" r="16" fill={COLORS.red} />
          <circle cx="360" cy="360" r="8" fill="white" />
        </svg>
      </AbsoluteFill>

      {/* Horizontal speed lines */}
      <AbsoluteFill style={{ display: "flex", alignItems: "center", justifyContent: "center" }}>
        <div style={{
          position: "absolute",
          top: "calc(50% - 8px)",
          left: 0,
          width: `${interpolate(lineProgress1, [0, 1], [0, 38])}%`,
          height: 2,
          background: "linear-gradient(90deg, transparent, rgba(255,0,0,0.6))",
          opacity: lineProgress1,
        }} />
        <div style={{
          position: "absolute",
          top: "calc(50% + 8px)",
          right: 0,
          width: `${interpolate(lineProgress2, [0, 1], [0, 38])}%`,
          height: 2,
          background: "linear-gradient(270deg, transparent, rgba(255,0,0,0.6))",
          opacity: lineProgress2,
        }} />
      </AbsoluteFill>

      {/* ── Central number + label ── */}
      <AbsoluteFill style={{
        display: "flex", flexDirection: "column",
        alignItems: "center", justifyContent: "center",
      }}>
        {/* Blurred glow behind number */}
        <div style={{
          position: "absolute",
          fontSize: 500,
          fontWeight: 900,
          color: COLORS.red,
          filter: "blur(80px)",
          opacity: interpolate(counterProgress, [0, 1], [0, 0.4]),
          userSelect: "none",
          lineHeight: 1,
          letterSpacing: "-0.06em",
        }}>
          {counter}
        </div>

        {/* Main counter */}
        <div style={{
          opacity: counterProgress,
          transform: `scale(${interpolate(counterProgress, [0, 1], [0.5, 1])}) translateY(${interpolate(counterProgress, [0, 1], [80, 0])}px)`,
          position: "relative",
          lineHeight: 0.9,
          textAlign: "center",
        }}>
          <div style={{
            fontSize: 500,
            fontWeight: 900,
            letterSpacing: "-0.06em",
            background: `linear-gradient(160deg, #FFFFFF 30%, ${COLORS.red} 100%)`,
            WebkitBackgroundClip: "text",
            WebkitTextFillColor: "transparent",
            textAlign: "center",
          }}>
            {counter}
          </div>
        </div>

        {/* HOURS */}
        <div style={{
          opacity: hoursProgress,
          transform: `translateY(${interpolate(hoursProgress, [0, 1], [60, 0])}px)`,
          marginTop: -30,
          display: "flex",
          alignItems: "center",
          gap: 36,
        }}>
          <div style={{
            width: 280,
            height: 3,
            background: "linear-gradient(90deg, transparent, rgba(255,255,255,0.5))",
            borderRadius: 2,
          }} />
          <div style={{
            fontSize: 96,
            fontWeight: 900,
            color: COLORS.white,
            letterSpacing: "0.35em",
            textTransform: "uppercase",
          }}>
            HOURS
          </div>
          <div style={{
            width: 280,
            height: 3,
            background: "linear-gradient(90deg, rgba(255,255,255,0.5), transparent)",
            borderRadius: 2,
          }} />
        </div>

        {/* Sub-label */}
        <div style={{
          opacity: subProgress,
          transform: `translateY(${interpolate(subProgress, [0, 1], [30, 0])}px)`,
          marginTop: 40,
          fontSize: 48,
          fontWeight: 500,
          color: "rgba(255,255,255,0.5)",
          letterSpacing: "0.12em",
          textTransform: "uppercase",
        }}>
          uploaded every minute
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

