const DataNode: React.FC<{
  item: typeof DATA_TARGETS[number];
  angle: number;
  radius: number;
}> = ({ item, angle, radius }) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const progress = spring({ frame, fps, delay: item.delay, config: { damping: 200 } });
  const lineProgress = spring({ frame, fps, delay: item.delay - 8, config: { damping: 200 } });

  const rad = (angle * Math.PI) / 180;
  const x = Math.cos(rad) * radius;
  const y = Math.sin(rad) * radius;

  return (
    <>
      {/* Animated connecting line */}
      <div style={{
        position: "absolute",
        top: "50%",
        left: "50%",
        width: radius * lineProgress,
        height: 2,
        background: `linear-gradient(90deg, ${item.color}60, ${item.color}15)`,
        transformOrigin: "left center",
        transform: `rotate(${angle}deg)`,
        opacity: lineProgress,
      }} />
      {/* Moving dot along the line */}
      <div style={{
        position: "absolute",
        top: "50%",
        left: "50%",
        width: 10,
        height: 10,
        borderRadius: "50%",
        backgroundColor: item.color,
        boxShadow: `0 0 16px ${item.color}`,
        transform: `translate(calc(-50% + ${x * Math.min(lineProgress * 1.2, 1)}px), calc(-50% + ${y * Math.min(lineProgress * 1.2, 1)}px))`,
        opacity: Math.min(lineProgress * 2, 1),
      }} />
      {/* Label node */}
      <div style={{
        position: "absolute",
        top: "50%",
        left: "50%",
        transform: `translate(calc(-50% + ${x * progress}px), calc(-50% + ${y * progress}px))`,
        opacity: progress,
      }}>
        <div style={{
          backgroundColor: "rgba(255,255,255,0.05)",
          backdropFilter: "blur(20px)",
          border: `2px solid ${item.color}50`,
          borderRadius: 20,
          padding: "22px 44px",
